eaeff88daa1d4da1bbb8b81dd7f1b05a4a1242d42cbc99a5dcac4b1576\nSELECT \n  DATE_FORMAT(bucket_end_date, \'%b %e, %Y\') AS `End Date`,\n  CONCAT(\n    DATE_FORMAT(DATE_SUB(bucket_end_date, INTERVAL 6 DAY), \'%b %e\'), \n    \' - \', \n    DATE_FORMAT(bucket_end_date, \'%b %e, %Y\')\n  ) AS `Date Range`,\n  `count`\nFROM (\n  SELECT\n    DATE_SUB(\n      CURDATE(), \n      INTERVAL (FLOOR(DATEDIFF(\n        CURDATE(), \n        DATE(`papers`.`created_at`)\n      ) / 7) * 7) DAY\n    ) AS bucket_end_date,\n    COUNT(*) AS `count`\n  FROM\n    `papers`\n  WHERE\n    `papers`.`created_at` <= NOW()\n  GROUP BY\n    bucket_end_date\n) AS grouped_data\nORDER BY\n  bucket_end_date ASC; [90022-214]',13371339,NULL,NULL,NULL,1,NULL,NULL,NULL,NULL,NULL,NULL,_binary '\0',NULL,NULL,NULL),(889,_binary 'D\◊’≥ì0:\Ÿyx\ \ ¡åçî±\ci\≈€Ö®\Ù∑\÷\ﬂ','2026-05-12 03:49:48.021490',9,5,_binary '\0','ad-hoc',NULL,13371339,NULL,NULL,NULL,2,_binary '\0',NULL,_binary '\0',NULL,NULL,NULL,_binary '\0',NULL,NULL,NULL),(890,_binary 'ekã\Ù\∆\"-≠&c≥f87èR\ÓÄ%Tá\È¿ï4FêtõQå','2026-05-12 03:52:49.614178',97,5,_binary '\0','question',NULL,13371339,47,NULL,NULL,2,_binary '\0',NULL,_binary '\0',NULL,NULL,NULL,_binary '\0',NULL,NULL,NULL),(891,_binary ',*º9†g≤\…¿b 9+^|\Ó˚#\ﬁH6L]l|4D^èç','2026-05-12 03:53:33.746175',9,5,_binary '\0','ad-hoc',NULL,13371339,NULL,NULL,NULL,2,_binary '\0',NULL,_binary '\0',NULL,NULL,NULL,_binary '\0',NULL,NULL,NULL),(892,_binary 'Q˙°˝\À$Ñs±‡±´ü\Í\≈\ZO\Ô\Ÿ\Ùç\Z!\ÊÄá\·','2026-05-12 03:55:28.334718',33,5,_binary '\0','dashboard',NULL,13371339,47,2,NULL,2,_binary '\0',NULL,_binary '\0',NULL,NULL,NULL,_binary '\0',NULL,NULL,NULL),(893,_binary 'Q˙°˝\À$Ñs±‡±´ü\Í\≈\ZO\Ô\Ÿ\Ùç\Z!\ÊÄá\·','2026-05-12 03:55:34.481387',37,5,_binary '\0','question',NULL,13371339,47,NULL,NULL,2,_binary '\0',NULL,_binary '\0',NULL,NULL,NULL,_binary '\0',NULL,NULL,NULL),(894,_binary 'Q˙°˝\À$Ñs±‡±´ü\Í\≈\ZO\Ô\Ÿ\Ùç\Z!\ÊÄá\·','2026-05-12 03:56:50.883127',43,5,_binary '\0','question',NULL,13371339,47,NULL